select 

from sh_idle_item
where (idle_name LIKE "%"#{findValue}"%" or idle_details LIKE "%"#{findValue}"%") and idle_status = 1 order by id desc limit #{begin}, #{nums}

select

from sh_idle_item
where idle_label = #{idleLabel}  and idle_status = 1 order by id desc limit #{begin}, #{nums}

select

from sh_idle_item
where idle_status = #{status} order by id desc limit #{offset}, #{limit}

mapper.update:
UPDATE sh_idle_item
SET idle_stock = idle_stock - #{quantity,jdbcType=INTEGER}
WHERE id = #{idleId,jdbcType=BIGINT} AND idle_stock >= #{quantity,jdbcType=INTEGER}

UPDATE sh_idle_item
SET sold_count = IFNULL(sold_count, 0) + #{quantity,jdbcType=INTEGER}
WHERE id = #{idleId,jdbcType=BIGINT}

UPDATE sh_idle_item
SET avg_rating = #{avgRating,jdbcType=DECIMAL},
    review_count = #{reviewCount,jdbcType=INTEGER}
WHERE id = #{idleId,jdbcType=BIGINT}
